<script setup>
import {computed,ref} from 'vue';import {Bookmark,Pin,Trash2,Pencil} from '@lucide/vue';
import {state,dispatch,notify} from '../state';import {t,number,errorText} from '../i18n';import {integer} from '../../core/shared.mjs';
import {workProgress,workMarkers,scopedWorkMarker,workMarkerContext,WORK_KINDS,WORK_MARKER_LIMIT} from '../../core/work-companion.mjs';
import EntityForm from './EntityForm.vue';
const props=defineProps({project:Object,patternId:String,revision:Object,cursor:Object,selectedColor:Number,workType:String,blocked:Boolean});const emit=defineEmits(['goto','select-color']);
const form=ref(null),error=ref(''),busy=ref(false),completedSignature=computed(()=>props.project.completed.join('|'));
const summary=computed(()=>workProgress(props.revision,completedSignature.value?completedSignature.value.split('|'):[]));
const markers=computed(()=>workMarkers(props.project.view)),current=computed(()=>markers.value.filter(m=>m.patternId===props.patternId&&m.revisionId===props.revision.id)),other=computed(()=>markers.value.filter(m=>!current.value.includes(m)));
const context=marker=>scopedWorkMarker(marker)?workMarkerContext(state.value,marker):null;
function reference(marker){const value=context(marker);return value?.color?`${value.color.brand} ${value.color.code} · ${value.color.symbol}`:''}
function open(kind='bookmark',marker=null){
 if(props.blocked||busy.value)return;const legacy=marker&&!scopedWorkMarker(marker),operation=crypto.randomUUID(),scope={projectId:props.project.id,patternId:props.patternId,revisionId:props.revision.id};
 form.value={title:legacy?t('workAssignMarker'):marker?t('workEditMarker'):t(kind==='parked'?'workParkThread':'workAddBookmark'),help:()=>t(legacy?'workAssociationHelp':'workMarkerHelp',{revision:props.revision.name||props.revision.id}),
 fields:[{key:'kind',label:()=>t('type'),type:'select',required:true,options:[{value:'bookmark',label:()=>t('workBookmark')},{value:'parked',label:()=>t('workParked')}]},
 {key:'column',label:()=>t('workColumn'),type:'number',required:true,help:()=>t('workCoordinateLimit',{maximum:props.revision.width})},
 {key:'row',label:()=>t('workRow'),type:'number',required:true,help:()=>t('workCoordinateLimit',{maximum:props.revision.height})},
 {key:'color',label:()=>t('workThreadReference'),type:'select',wide:true,help:()=>t('workParkedColorHelp'),options:props.revision.colors.map((c,index)=>({value:String(index),label:`${c.brand} ${c.code} · ${c.symbol} · ${c.name}`}))},
 {key:'stitchKind',label:()=>t('workStitchContext'),type:'select',options:WORK_KINDS.map(value=>({value,label:()=>t(`workKind_${value}`)}))},
 {key:'note',label:()=>t('workMarkerNote'),type:'textarea',wide:true,max:500},
 ...(legacy?[{key:'confirmAssociation',type:'checkbox',label:()=>t('workConfirmAssociation',{revision:props.revision.name||props.revision.id}),required:true,wide:true}]:[])],
 initial:{kind:marker?.kind||kind,column:(marker?.x??props.cursor.x)+1,row:(marker?.y??props.cursor.y)+1,color:marker?(marker.color===null||marker.color===undefined?'':String(marker.color)):kind==='parked'&&props.revision.colors.length?String(props.selectedColor):'',stitchKind:marker?.stitchKind??(props.workType!=='all'?props.workType:''),note:marker?.note??'',confirmAssociation:false},
 submit:draft=>dispatch('project.work.marker.save',{...scope,confirmAssociation:draft.confirmAssociation===true,marker:{id:marker?.id??operation,kind:draft.kind,x:integer(draft.column,'column',{min:1,max:props.revision.width})-1,y:integer(draft.row,'row',{min:1,max:props.revision.height})-1,color:draft.color===''?null:Number(draft.color),stitchKind:draft.stitchKind||null,note:draft.note}},operation)};
}
async function remove(marker){if(busy.value)return;busy.value=true;error.value='';try{await dispatch('project.work.marker.remove',{projectId:props.project.id,markerId:marker.id});notify()}catch(caught){error.value=errorText(caught)}finally{busy.value=false}}
defineExpose({open});
</script>
<template><div class="stack"><section class="panel"><div class="panel-heading"><h2>{{t('workRemainingTitle')}}</h2><span class="badge">{{t('workRemainingCount',{count:number(summary.remaining,0)})}}</span></div><div class="panel-body"><p class="field-help">{{t('workCountHelp')}}</p><div class="table-wrap"><table><thead><tr><th>{{t('color')}}</th><th>{{t('workKind_full')}}</th><th>{{t('workKind_half')}}</th><th>{{t('workKind_backstitch')}}</th><th>{{t('remaining')}}</th></tr></thead><tbody><tr v-for="row in summary.byColor.filter(row=>row.total)" :key="row.color"><td><button class="button text small" @click="emit('select-color',row.color)">{{revision.colors[row.color].symbol}} · {{revision.colors[row.color].brand}} {{revision.colors[row.color].code}}</button></td><td v-for="kind in WORK_KINDS" :key="kind">{{row.kinds[kind].total?`${number(row.kinds[kind].done,0)} / ${number(row.kinds[kind].total,0)}`:'—'}}</td><td>{{number(row.remaining,0)}}</td></tr></tbody></table></div></div></section>
<section class="panel"><div class="panel-heading"><h2>{{t('workMarkers')}}</h2><span class="badge">{{markers.length}} / {{WORK_MARKER_LIMIT}}</span></div><div class="panel-body"><p class="field-help">{{t('workMarkerHelp',{revision:revision.name||revision.id})}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p><div class="toolbar"><button class="button small" :disabled="blocked||busy||markers.length>=WORK_MARKER_LIMIT" @click="open('bookmark')"><Bookmark :size="15"/>{{t('workAddBookmark')}}</button><button class="button small" :disabled="blocked||busy||!revision.colors.length||markers.length>=WORK_MARKER_LIMIT" @click="open('parked')"><Pin :size="15"/>{{t('workParkThread')}}</button></div><p v-if="!current.length" class="field-help">{{t('workNoCurrentMarkers')}}</p><article v-for="marker in current" :key="marker.id" class="form-section"><strong>{{t(marker.kind==='parked'?'workParked':'workBookmark')}} · {{marker.x+1}}, {{marker.y+1}}</strong><p v-if="reference(marker)" class="field-help">{{reference(marker)}}<template v-if="marker.stitchKind"> · {{t(`workKind_${marker.stitchKind}`)}}</template></p><p v-if="marker.note" style="white-space:pre-wrap;overflow-wrap:anywhere">{{marker.note}}</p><div class="actions"><button class="button small" @click="emit('goto',marker)">{{t('workGotoMarker')}}</button><button class="icon-button" :disabled="blocked||busy" :aria-label="`${t('edit')}: ${marker.note||`${marker.x+1}, ${marker.y+1}`}`" @click="open(marker.kind,marker)"><Pencil :size="15"/></button><button class="icon-button" :disabled="blocked||busy" :aria-label="`${t('remove')}: ${marker.note||`${marker.x+1}, ${marker.y+1}`}`" @click="remove(marker)"><Trash2 :size="15"/></button></div></article>
<details v-if="other.length" class="form-section"><summary>{{t('workOtherMarkers',{count:other.length})}}</summary><p class="notice">{{t('workOtherMarkerHelp')}}</p><article v-for="marker in other" :key="marker.id" class="form-section"><strong>{{marker.x+1}}, {{marker.y+1}}</strong><p class="field-help">{{context(marker)?`${context(marker).pattern.name} · ${context(marker).revision.name||marker.revisionId}`:t('workUnassignedMarker')}}<template v-if="reference(marker)"> · {{reference(marker)}}</template></p><p style="white-space:pre-wrap;overflow-wrap:anywhere">{{marker.note}}</p><div class="actions"><button v-if="!scopedWorkMarker(marker)" class="button small" :disabled="blocked||busy" @click="open('bookmark',marker)">{{t('workAssignMarker')}}</button><button class="button small" :disabled="blocked||busy" :aria-label="`${t('remove')}: ${marker.note||`${marker.x+1}, ${marker.y+1}`}`" @click="remove(marker)">{{t('remove')}}</button></div></article></details></div></section>
<EntityForm v-if="form" :title="form.title" :help="typeof form.help==='function'?form.help():form.help" :fields="form.fields" :initial="form.initial" :submit="form.submit" @close="form=null" @saved="form=null;notify()"/>
</div></template>
